{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 실행 계획에서 병목을 식별하고, 확인한 병목에 맞춰 개선 조치를 선택했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "실행 계획에서 확인한 병목을 근거로 쿼리 개선 조치를 정해야 했다.",
          "action": "실행 계획에서 확인한 조회 조건과 테이블 접근 특성을 인덱스 추가 또는 조인 정리의 선택 근거로 설명한다.",
          "result": "지원서에 기재된 조회 시간 단축은 답변의 배경으로만 참고하며, 추가적인 성과 설명은 요구하지 않는다."
        },
        "expectedEvidence": [
          "실행 계획에서 확인한 병목과 선택한 쿼리 개선 조치 사이의 연결 근거",
          "판단에 사용한 조회 조건, 테이블 접근 방식 또는 조인 관련 정보",
          "해당 정보가 쿼리의 어느 부분을 바꿔야 한다고 판단하게 했는지에 대한 설명"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄였을 때, 실행 계획을 바탕으로 개선 조치를 정한 판단 근거는 무엇이었나요?",
      "answerTip": "직접 확인한 사실을 중심으로 차분하게 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "신고 목록 조회의 실제 조건이나 테이블 접근 특성 등 실행 계획에서 읽은 정보를 짚고, 그 정보가 선택한 쿼리 개선 조치의 근거가 된 연결을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "신고 목록 조회 쿼리의 개선 근거를 제시하지만, 인덱스가 조회를 빠르게 한다거나 전체 조인을 줄여야 한다는 일반적인 설명에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 조회의 실행 계획과 개선 조치를 연결하는 판단 근거 없이, 수행한 수정이나 조회 시간 단축 수치만 반복하거나 다른 개발 경험을 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 좁힌 장애 원인에 따라 즉시 복구와 재발 방지를 구분하여 대응 순서를 정할 수 있는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔다.",
          "task": "로그로 확인한 스케줄러 중복 실행 원인에 맞춰 장애 대응 순서를 정해야 했다.",
          "action": "두 서버의 동시 실행을 보여 준 로그 단서를 토대로, 중복 실행을 막는 조치와 배포 체크리스트 보완을 어떤 순서로 배치했는지 설명한다.",
          "result": "중복 알림 대응의 흐름을 이해하기 위한 참고로만 활용하며, 재발 여부나 조치 효과의 입증은 요구하지 않는다."
        },
        "expectedEvidence": [
          "로그에서 좁힌 원인에 근거해 정한 장애 대응 순서",
          "대응 순서를 정하는 데 사용한 두 서버의 스케줄러 동시 실행 단서",
          "즉시 중복 실행을 막는 단계와 이후 반복을 방지하는 단계의 구분"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 추적했을 때, 로그에서 확인한 원인을 바탕으로 정한 장애 대응 순서는 무엇이었나요?",
      "answerTip": "당시 직접 맡았던 일을 중심으로 순서대로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "알림 중복 발송 로그의 동시 실행 단서를 대응 순서에 연결하고, 중복 실행을 막는 조치와 반복 방지 조치를 실제 작업 수준으로 구분해 선후 관계를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "알림 중복 발송에 대해 먼저 복구하고 이후 재발을 방지한다는 대응 순서는 제시하지만, 로그로 확인한 원인에 따른 구체적인 단계 구분은 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "알림 중복 발송의 원인이나 잠금 적용 사실만 언급하고, 로그에서 확인한 원인에 따른 장애 대응 순서는 제시하지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "인터뷰에서 파악한 요청의 목적과 필요성을 근거로 요구사항 정의서의 구현 범위를 결정할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰하고 요구사항 정의서를 작성한 상황.",
          "task": "인터뷰에서 나온 요청을 검토해 요구사항 정의서에 담을 구현 범위를 정하는 일.",
          "action": "특정 인터뷰 내용에서 파악한 필요성이나 제약을 구현 범위 결정의 근거로 연결한 설명.",
          "result": "해당 판단에 따라 요구사항 정의서에 정리된 구현 범위."
        },
        "expectedEvidence": [
          "인터뷰 내용 중 무엇을 근거로 예약 서비스의 구현 범위를 정했는지에 대한 설명",
          "근거로 삼은 구체적인 요청과 그 요청에서 파악한 목적 또는 제약"
        ]
      },
      "question": "세탁소 5곳 인터뷰로 요구사항 정의서를 작성했을 때, 예약 서비스의 구현 범위를 정한 판단 근거는 무엇이었나요?",
      "answerTip": "직접 맡았던 일을 중심으로 한 장면을 떠올려 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "세탁소 인터뷰에서 나온 특정 요청의 목적이나 제약을 짚고, 이를 근거로 요구사항 정의서의 구현 범위를 어떻게 정했는지 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항 정의서의 구현 범위를 정한 근거를 말하지만, 중요도나 개발 가능성 같은 일반적인 기준만 제시하고 실제 세탁소 인터뷰 내용과 연결하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서의 구현 범위를 정한 근거를 제시하지 않거나, 인터뷰 진행 사실이나 문서 작성 사실만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "서비스의 예외 상황을 개발자와 디자이너가 구현할 수 있는 화면 상태와 동작으로 구체화해 화면설계서에 명세할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성한 상황.",
          "task": "취소 흐름의 예외 상황을 화면 단위의 명세로 구체화하는 일.",
          "action": "취소 예외 상황 하나에 대해 화면설계서에 적은 발생 조건, 화면 상태와 동작, 안내 표현을 설명.",
          "result": "해당 예외 상황을 처리하는 화면 명세가 화면설계서에 표현된 형태."
        },
        "expectedEvidence": [
          "취소 예외 상황 하나를 다룬 실제 화면 명세에 대한 설명",
          "해당 예외가 발생하는 조건에 연결된 화면 상태나 조작 동작",
          "해당 화면에서 사용자에게 표시하도록 적은 안내 표현"
        ]
      },
      "question": "화면설계서 28장을 작성했을 때, 동네 세탁소 예약 서비스의 취소 예외 상황 하나를 다룬 화면 명세는 무엇이었나요?",
      "answerTip": "기억나는 장면 하나를 골라 직접 작성한 부분을 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "취소 예외 상황 하나의 발생 조건에 맞춰 화면설계서에 명시한 화면 상태, 조작 동작, 안내 표현을 실제 화면을 떠올릴 수 있는 수준으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "취소 예외 상황의 화면 명세를 설명하지만, 오류를 표시하거나 안내 문구를 넣었다는 일반적인 설명에 그쳐 해당 화면의 상태나 동작을 식별하기 어렵다."
          ]
        },
        "poor": {
          "criteria": [
            "취소 예외 상황을 다룬 화면 명세를 제시하지 않거나, 화면설계서의 장수나 사용 도구만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량을 확인하는 과정에서 이상을 식별하고, 투약을 중단해 담당의에게 확인할 필요가 있다고 판단한 근거를 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력되어 있었던 상황",
          "task": "처방 용량의 적절성이 확인되지 않은 상태에서 투약 진행 여부를 판단해야 했던 상황",
          "action": "처방 용량을 어떤 정보와 비교했고, 어떤 불일치를 근거로 투약을 멈추고 담당의에게 확인하기로 했는지 설명",
          "result": "담당의 확인을 통해 처방 입력 오류임을 확인한 경험"
        },
        "expectedEvidence": [
          "처방대로 투약하지 않고 담당의에게 확인하기로 한 판단 근거",
          "진통제 처방 용량의 이상 여부를 판단할 때 비교한 정보",
          "비교한 정보와 실제 처방 사이에서 확인한 구체적인 차이"
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어왔던 때, 처방대로 투약하지 않고 담당의에게 확인하기로 한 판단 근거는 무엇이었나요?",
      "answerTip": "당시 장면을 떠올리며 본인이 판단한 부분을 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방 용량을 비교한 실제 정보와 처방 사이의 차이를 짚어, 투약을 멈추고 담당의 확인이 필요하다고 판단한 근거를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 용량이 평소보다 많아 담당의 확인이 필요했다고 설명하지만, 용량을 비교한 정보나 해당 환자의 처방에서 확인한 차이는 구체적으로 밝히지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 멈추고 담당의에게 확인하기로 한 판단 근거를 말하지 않거나, 처방 확인과 무관한 업무를 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "간호 기록에 남긴 환자 상태 변화에서 이상 징후를 파악하고, 이를 근거로 담당 의사에게 전달할 핵심 정보를 정할 수 있는지 검증한다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "수술 후 환자의 혈압이 120/80mmHg에서 85/55mmHg로 떨어진 것을 간호 기록에 남기는 상황",
          "task": "기록된 혈압 변화를 근거로 담당 의사에게 즉시 보고할 핵심 정보를 정하는 과제",
          "action": "간호 기록의 이전 혈압과 저하된 혈압을 측정 시점에 연결해, 환자의 상태 변화가 드러나는 보고 정보로 정리",
          "result": "담당 의사가 혈압 저하의 정도와 발생 시점을 파악할 수 있는 보고를 예상"
        },
        "expectedEvidence": [
          "간호 기록의 혈압 변화를 근거로 선정한 즉시 보고할 핵심 정보",
          "이전 혈압과 저하된 혈압을 연결한 상태 변화의 표현",
          "혈압 변화가 발생한 시점을 드러내는 기록 정보"
        ]
      },
      "question": "수술 후 환자의 혈압이 120/80mmHg에서 85/55mmHg로 떨어진 것을 간호 기록에 남긴다면, 그 기록에서 담당 의사에게 즉시 보고할 핵심 정보는 무엇인가요?",
      "answerTip": "가정된 상황 속에서 실제로 말하듯 답변해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "간호 기록의 이전 혈압과 저하된 혈압을 측정 시점에 연결하여, 담당 의사에게 보고할 혈압 변화 정보를 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "간호 기록에서 혈압이 낮아졌다는 사실을 담당 의사에게 보고하겠다고 하지만, 이전 수치와의 변화나 측정 시점을 연결한 보고 정보는 제시하지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "간호 기록을 근거로 담당 의사에게 전달할 혈압 변화 정보를 제시하지 않거나, 보고 정보 대신 투약이나 처치 이야기만 한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "주어진 하중 조건을 축에 작용하는 힘으로 해석하고, 그 해석을 근거로 축 지름을 정했는지 확인한다.",
